const moneyFormatter = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  maximumFractionDigits: 0,
});

function formatMoney(value: number) {
  return moneyFormatter.format(value);
}

function formatFileSize(bytes: number | null | undefined) {
  if (!bytes || bytes <= 0) {
    return "Size pending";
  }

  const units = ["B", "KB", "MB", "GB"];
  let value = bytes;
  let unitIndex = 0;

  while (value >= 1024 && unitIndex < units.length - 1) {
    value /= 1024;
    unitIndex += 1;
  }

  return `${value >= 10 || unitIndex === 0 ? value.toFixed(0) : value.toFixed(1)} ${units[unitIndex]}`;
}

function getFormString(formData: FormData, key: string, fallback = "") {
  const value = formData.get(key);
  return typeof value === "string" && value.trim() ? value.trim() : fallback;
}

function getOptionalFormString(formData: FormData, key: string) {
  const value = getFormString(formData, key);
  return value || null;
}

function normalizeCrmTextInput(value: string | null | undefined) {
  return (value ?? "").trim().replace(/\s+/g, " ");
}

function getNormalizedFormString(formData: FormData, key: string, fallback = "") {
  const value = formData.get(key);
  const normalized = typeof value === "string" ? normalizeCrmTextInput(value) : "";

  return normalized || fallback;
}

function getNormalizedOptionalFormString(formData: FormData, key: string) {
  const value = getNormalizedFormString(formData, key);
  return value || null;
}

function getNormalizedEmailFormString(formData: FormData, key: string) {
  const value = getNormalizedFormString(formData, key);

  if (!value) {
    return null;
  }

  return normalizeLeadIntakeEmail(value) ?? value.toLowerCase();
}

function getNormalizedPhoneFormString(formData: FormData, key: string) {
  const value = getNormalizedFormString(formData, key);

  return value ? normalizeLeadIntakePhone(value) ?? value : null;
}

function isValidOptionalEmail(value: string | null | undefined) {
  return !value || normalizeLeadIntakeEmail(value) !== null;
}

function getOptionalRelation(formData: FormData, key: string) {
  const value = getFormString(formData, key);
  return value && value !== "none" ? value : null;
}

function getOptionalFormFile(formData: FormData, key: string) {
  const value = formData.get(key);
  return value instanceof File && value.size > 0 ? value : null;
}

function getFormNumber(formData: FormData, key: string) {
  const value = getFormString(formData, key).replace(/[^0-9.]/g, "");
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}

function companyInitials(company: CompanyRecord | null | undefined) {
  if (!company) {
    return "OS";
  }

  return company.name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0])
    .join("")
    .toUpperCase();
}

function getCompanyBrandColor(company: CompanyRecord | null | undefined) {
  if (company && isPaintingCompany(company)) {
    return "var(--wt-painting-orange)";
  }

  if (
    !company ||
    company.trade === "roofing" ||
    company.workflow_profile === "roofing"
  ) {
    return "var(--wt-roofing-purple)";
  }

  const brandColor = company?.brand_color?.toLowerCase();

  if (!brandColor || brandColor === "#0284c7" || brandColor === "#0ea5e9") {
    return "var(--wt-roofing-purple)";
  }

  return company.brand_color ?? "var(--wt-roofing-purple)";
}

function companyTradeLabel(company: CompanyRecord | null | undefined) {
  if (!company) {
    return "All-company workspace";
  }

  return `${company.trade === "both" ? "Shared" : company.trade} workflow`;
}

function statusLabel(status: LeadStatus) {
  return leadStatuses.find((item) => item.value === status)?.label ?? status;
}

function pipelineStageLabel(stage: PipelineStage) {
  return pipelineStages.find((item) => item.value === stage)?.label ?? stage;
}

function leadStatusForPipelineStage(stage: PipelineStage): LeadStatus {
  if (stage === "new_lead") {
    return "new";
  }

  if (stage === "estimate_scheduled") {
    return "qualified";
  }

  if (
    stage === "approved" ||
    stage === "job_scheduled" ||
    stage === "completed" ||
    stage === "paid"
  ) {
    return "won";
  }

  return stage;
}

function getLeadPipelineStageFromForm(formData: FormData) {
  const value = getNormalizedFormString(formData, "pipeline_stage", "new_lead");

  return pipelineStages.some((stage) => stage.value === value)
    ? (value as PipelineStage)
    : "new_lead";
}

function buildLeadInputFromFormData(formData: FormData, companies: CompanyRecord[]) {
  const pipelineStage = getLeadPipelineStageFromForm(formData);

  return {
    company_id: getNormalizedFormString(formData, "company_id", companies[0]?.id),
    contact_name: getNormalizedFormString(formData, "contact_name"),
    phone: getNormalizedPhoneFormString(formData, "phone"),
    email: getNormalizedEmailFormString(formData, "email"),
    property_address: getNormalizedFormString(formData, "property_address"),
    city: getNormalizedOptionalFormString(formData, "city"),
    state: getNormalizedFormString(formData, "state", "AZ"),
    postal_code: getNormalizedOptionalFormString(formData, "postal_code"),
    service_type: getNormalizedFormString(formData, "service_type", "roofing") as ServiceType,
    source: getNormalizedFormString(formData, "source", "Website"),
    status: leadStatusForPipelineStage(pipelineStage),
    pipeline_stage: pipelineStage,
    priority: getNormalizedFormString(formData, "priority", "normal") as LeadPriority,
    estimated_value: getFormNumber(formData, "estimated_value"),
    next_follow_up: getNormalizedOptionalFormString(formData, "next_follow_up"),
    notes: getNormalizedOptionalFormString(formData, "notes"),
  } satisfies LeadInput;
}

function createDemoLeadRecord(input: LeadInput): LeadRecord {
  const now = new Date().toISOString();

  return {
    id: `demo-lead-${Date.now()}`,
    company_id: input.company_id,
    customer_id: null,
    contact_name: input.contact_name,
    phone: input.phone ?? null,
    email: input.email ?? null,
    property_address: input.property_address,
    city: input.city ?? null,
    state: input.state ?? "AZ",
    postal_code: input.postal_code ?? null,
    latitude: input.latitude ?? null,
    longitude: input.longitude ?? null,
    google_place_id: input.google_place_id ?? null,
    address_verified_at: input.address_verified_at ?? null,
    service_type: input.service_type,
    source: input.source ?? "Website",
    status: input.status ?? "new",
    pipeline_stage: input.pipeline_stage ?? "new_lead",
    priority: input.priority ?? "normal",
    estimated_value: input.estimated_value ?? 0,
    next_follow_up: input.next_follow_up ?? null,
    notes: input.notes ?? null,
    created_by: null,
    created_at: now,
    updated_at: now,
  };
}

