function inspectionStatusTone(status: InspectionStatus): "blue" | "green" | "amber" {
  if (status === "completed" || status === "passed" || status === "no_work_needed") {
    return "green";
  }

  if (
    status === "follow_up_required" ||
    status === "needs_review" ||
    status === "failed" ||
    status === "canceled"
  ) {
    return "amber";
  }

  return "blue";
}

