function dateKey(value: string | null | undefined) {
  return value ? value.slice(0, 10) : null;
}

function isTodayDate(value: string | null | undefined, today: string) {
  return dateKey(value) === today;
}

function isUpcomingDate(value: string | null | undefined, today: string) {
  const key = dateKey(value);
  return Boolean(key && key >= today);
}

function isRecentDate(value: string | null | undefined, today: string, days: number) {
  const key = dateKey(value);

  if (!key) {
    return false;
  }

  const current = new Date(`${today}T00:00:00`).getTime();
  const target = new Date(`${key}T00:00:00`).getTime();
  const maxAge = days * 24 * 60 * 60 * 1000;

  return target <= current && target >= current - maxAge;
}

function sortByNewest<T extends { created_at?: string; updated_at?: string }>(
  items: T[],
) {
  return [...items].sort((a, b) =>
    (b.updated_at ?? b.created_at ?? "").localeCompare(a.updated_at ?? a.created_at ?? ""),
  );
}

function sortByDateField<T>(
  items: T[],
  getValue: (item: T) => string | null | undefined,
) {
  return [...items].sort((a, b) => {
    const left = getValue(a) ?? "";
    const right = getValue(b) ?? "";
    return left.localeCompare(right);
  });
}

function getDashboardItemCompanyLabel(
  companyMap: Map<string, CompanyRecord>,
  companyId: string | null,
) {
  return companyId
    ? companyMap.get(companyId)?.short_name ?? companyMap.get(companyId)?.name ?? "Company"
    : "All companies";
}

function readCommandPaletteRecentIds() {
  if (typeof window === "undefined") {
    return [];
  }

  try {
    const parsed = JSON.parse(
      window.localStorage.getItem(commandPaletteRecentStorageKey) ?? "[]",
    );

    return Array.isArray(parsed)
      ? parsed.filter((item): item is string => typeof item === "string").slice(0, 10)
      : [];
  } catch {
    return [];
  }
}

function writeCommandPaletteRecentIds(ids: string[]) {
  if (typeof window === "undefined") {
    return;
  }

  window.localStorage.setItem(commandPaletteRecentStorageKey, JSON.stringify(ids.slice(0, 10)));
}

