  const handleSaveJob = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onError("");
    const formData = new FormData(event.currentTarget);
    const companyId = getFormString(
      formData,
      "company_id",
      snapshot.companies[0]?.id,
    );
    const company =
      companyMap.get(companyId) ??
      snapshot.companies.find((item) => item.id === companyId) ??
      null;
    const estimateId = getOptionalRelation(formData, "estimate_id");
    const scopeId = getOptionalRelation(formData, "scope_id");
    const requestedCustomerId = getOptionalRelation(formData, "customer_id");
    const requestedLeadId = getOptionalRelation(formData, "lead_id");
    const serviceType = getFormString(
      formData,
      "service_type",
      getDefaultServiceTypeForCompany(company),
    ) as ServiceType;
    const estimateCandidate = estimateId
      ? snapshot.estimates.find((estimate) => estimate.id === estimateId)
      : null;
    const scopeCandidate = scopeId
      ? snapshot.scopes.find((scope) => scope.id === scopeId)
      : null;
    const selectedEstimate =
      estimateCandidate &&
      estimateCandidate.company_id === companyId &&
      serviceTypeMatchesJobType(estimateCandidate.service_type, serviceType)
        ? estimateCandidate
        : null;
    const selectedScope =
      scopeCandidate &&
      scopeCandidate.company_id === companyId &&
      scopeCategoryMatchesJobType(scopeCandidate.category, serviceType)
        ? scopeCandidate
        : null;
    const customerId =
      requestedCustomerId ?? selectedEstimate?.customer_id ?? selectedScope?.customer_id ?? null;
    const leadId =
      requestedLeadId ?? selectedEstimate?.lead_id ?? selectedScope?.lead_id ?? null;
    const selectedCustomer = customerId
      ? snapshot.customers.find((customer) => customer.id === customerId)
      : null;
    const selectedLead = leadId ? snapshot.leads.find((lead) => lead.id === leadId) : null;
    const scheduledStartInput = getOptionalFormString(formData, "scheduled_start");
    const scheduledEndInput = getOptionalFormString(formData, "scheduled_end");
    const scheduledStart = scheduledStartInput
      ? fromDateTimeInputValue(scheduledStartInput)
      : null;
    const scheduledEnd = scheduledEndInput ? fromDateTimeInputValue(scheduledEndInput) : null;

    if (scheduledStart && scheduledEnd && scheduledEnd <= scheduledStart) {
      onError("Scheduled end must be after scheduled start.");
      return;
    }

    const address =
      getOptionalFormString(formData, "address") ??
      selectedEstimate?.location ??
      selectedCustomer?.property_address ??
      selectedLead?.property_address ??
      null;
    const total = getFormNumber(formData, "total") || selectedEstimate?.total || 0;
    const business =
      getFormString(formData, "business") ||
      selectedEstimate?.business ||
      company?.name ||
      "";
    const location =
      getFormString(formData, "location") ||
      selectedEstimate?.location ||
      getDefaultJobLocationForCompany(company);

    if (!business || !location) {
      onError("Job business and location are required.");
      return;
    }

    if (!isServiceAllowedForCompany(company, serviceType)) {
      onError(`${company?.name ?? "This company"} uses ${getDefaultServiceTypeForCompany(company)} jobs.`);
      return;
    }

    if (estimateId && !selectedEstimate) {
      onError(`Choose a ${serviceLabel(serviceType).toLowerCase()} estimate from ${company?.name ?? "this company"}.`);
      return;
    }

    if (scopeId && !selectedScope) {
      onError(`Choose a ${serviceLabel(serviceType).toLowerCase()} scope from ${company?.name ?? "this company"}.`);
      return;
    }

    if (
      (customerId &&
        !snapshot.customers.some(
          (customer) => customer.id === customerId && customer.company_id === companyId,
        )) ||
      (leadId &&
        !snapshot.leads.some(
          (lead) => lead.id === leadId && lead.company_id === companyId,
        )) ||
      (estimateId &&
        !selectedEstimate) ||
      (scopeId &&
        !selectedScope)
    ) {
      onError("Choose customer, lead, estimate, and scope records from the same company.");
      return;
    }

    const input: JobInput = {
      company_id: companyId,
      customer_id: customerId,
      lead_id: leadId,
      estimate_id: estimateId,
      scope_id: scopeId,
      business,
      location,
      title: getFormString(formData, "title", "New job"),
      service_type: serviceType,
      status: getFormString(formData, "status", "draft") as JobStatus,
      scheduled_start: scheduledStart,
      scheduled_end: scheduledEnd,
      start_date: scheduledStartInput?.slice(0, 10) ?? null,
      end_date: scheduledEndInput?.slice(0, 10) ?? null,
      crew_name: getOptionalFormString(formData, "crew_name"),
      project_manager: getOptionalFormString(formData, "project_manager"),
      address,
      property_address: address || "Address to confirm",
      scope_of_work:
        getOptionalFormString(formData, "scope_of_work") ??
        selectedEstimate?.scope_of_work ??
        selectedScope?.scope_body ??
        null,
      total,
      notes: getOptionalFormString(formData, "notes"),
    };

    try {
      setIsSaving(true);
      const savedJob = isDemoMode
        ? saveDemoJob(input)
        : selectedJob
          ? await updateJob(client, selectedJob.id, input)
          : await createJob(client, input);
      setSelectedJobId(savedJob.id);
      if (!isDemoMode) {
        await onReload();
      }
      onNotice(selectedJob ? "Job updated." : "Draft job created.");
    } catch (currentError) {
      onError(getCaughtErrorMessage(currentError, "Unable to save job."));
    } finally {
      setIsSaving(false);
    }
  };

  const handleUpdateJobStatus = async (status: JobStatus) => {
    if (!selectedJob) {
      return;
    }

    try {
      if (isDemoMode) {
        saveDemoJobStatus(status);
      } else {
        await updateJob(client, selectedJob.id, { status });
        await onReload();
      }
      onNotice(`Job moved to ${jobStatusLabel(status)}.`);
    } catch (currentError) {
      onError(getCaughtErrorMessage(currentError, "Unable to update job status."));
    }
  };

  const handleConfirmedJobStatusTransition = async (status: JobStatus) => {
    if (!selectedJob) {
      return;
    }

    if (
      !window.confirm(
        `Move ${selectedJob.title} to ${jobStatusLabel(status)}? This updates the job workflow status only.`,
      )
    ) {
      return;
    }

    await handleUpdateJobStatus(status);
  };

  const handleCreateJobTask = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    if (!selectedJob) {
      onError("Select or save a job before adding checklist tasks.");
      return;
    }

    const form = event.currentTarget;
    const formData = new FormData(form);
    const input: JobTaskInput = {
      job_id: selectedJob.id,
      title: getFormString(formData, "title"),
      description: getOptionalFormString(formData, "description"),
      status: getFormString(formData, "status", "todo") as JobTaskStatus,
      sort_order: selectedJobTasks.length,
    };

    if (!input.title) {
      onError("Add a checklist task title.");
      return;
    }

    if (selectedJobTaskTitles.has(input.title.trim().toLowerCase())) {
      onError("That checklist task already exists for this job.");
      return;
    }

    try {
      setProductionAction("create-task");
      if (isDemoMode) {
        saveDemoJobTask(input);
      } else {
        await createJobTask(client, input);
      }
      form.reset();
      if (!isDemoMode) {
        await onScrollPreservingReload();
      }
      onNotice("Checklist task added.");
    } catch (currentError) {
      onError(getCaughtErrorMessage(currentError, "Unable to add checklist task."));
    } finally {
      setProductionAction(null);
    }
  };

  const handleCreateSuggestedJobTask = async (title: string) => {
    if (!selectedJob) {
      onError("Select or save a job before adding checklist tasks.");
      return;
    }

    if (selectedJobTaskTitles.has(title.trim().toLowerCase())) {
      onError("That checklist task already exists for this job.");
      return;
    }

    try {
      setProductionAction(`suggest:${title}`);
      const input: JobTaskInput = {
        job_id: selectedJob.id,
        title,
        status: "todo",
        sort_order: selectedJobTasks.length,
      };

      if (isDemoMode) {
        saveDemoJobTask(input);
      } else {
        await createJobTask(client, input);
        await onScrollPreservingReload();
      }
      onNotice("Checklist task added.");
    } catch (currentError) {
      onError(getCaughtErrorMessage(currentError, "Unable to add checklist task."));
    } finally {
      setProductionAction(null);
    }
  };

  const handleUpdateJobTaskStatus = async (
    taskId: string,
    status: JobTaskStatus,
  ) => {
    try {
      setProductionAction(`status:${taskId}`);
      if (isDemoMode) {
        updateDemoJobTask(taskId, { status });
      } else {
        await updateJobTask(client, taskId, { status });
        await onScrollPreservingReload();
      }
      onNotice(`Checklist task marked ${jobTaskStatusLabel(status)}.`);
    } catch (currentError) {
      onError(getCaughtErrorMessage(currentError, "Unable to update checklist task."));
    } finally {
      setProductionAction(null);
    }
  };

  const handleEditJobTask = async (
    event: FormEvent<HTMLFormElement>,
    taskId: string,
  ) => {
    event.preventDefault();

    const formData = new FormData(event.currentTarget);
    const title = getFormString(formData, "title");

    if (!title) {
      onError("Add a checklist task title.");
      return;
    }

    const normalizedTitle = title.trim().toLowerCase();
    const duplicateTask = selectedJobTasks.some(
      (task) => task.id !== taskId && task.title.trim().toLowerCase() === normalizedTitle,
    );

    if (duplicateTask) {
      onError("That checklist task already exists for this job.");
      return;
    }

    try {
      setProductionAction(`edit:${taskId}`);
      const input = {
        title,
        description: getOptionalFormString(formData, "description"),
        status: getFormString(formData, "status", "todo") as JobTaskStatus,
      };

      if (isDemoMode) {
        updateDemoJobTask(taskId, input);
      } else {
        await updateJobTask(client, taskId, input);
      }
      updateUiPreservingScrollPosition(() => setEditingTaskId(null));
      if (!isDemoMode) {
        await onScrollPreservingReload();
      }
      onNotice("Checklist task updated.");
    } catch (currentError) {
      onError(getCaughtErrorMessage(currentError, "Unable to update checklist task."));
    } finally {
      setProductionAction(null);
    }
  };

  const handleDeleteJobTask = async (taskId: string) => {
    if (!window.confirm("Delete this checklist task?")) {
      return;
    }

    try {
      setProductionAction(`delete:${taskId}`);
      if (isDemoMode) {
        onDemoSnapshotChange((currentSnapshot) => ({
          ...currentSnapshot,
          jobTasks: currentSnapshot.jobTasks.filter((task) => task.id !== taskId),
        }));
      } else {
        await deleteJobTask(client, taskId);
      }
      updateUiPreservingScrollPosition(() =>
        setEditingTaskId((currentId) => (currentId === taskId ? null : currentId)),
      );
      if (!isDemoMode) {
        await onScrollPreservingReload();
      }
      onNotice("Checklist task deleted.");
    } catch (currentError) {
      onError(getCaughtErrorMessage(currentError, "Unable to delete checklist task."));
    } finally {
      setProductionAction(null);
    }
  };

  const handleMoveJobTask = async (taskId: string, direction: -1 | 1) => {
    const currentIndex = selectedJobTasks.findIndex((task) => task.id === taskId);
    const nextIndex = currentIndex + direction;

    if (currentIndex < 0 || nextIndex < 0 || nextIndex >= selectedJobTasks.length) {
      return;
    }

    const reorderedTasks = [...selectedJobTasks];
    const [movedTask] = reorderedTasks.splice(currentIndex, 1);
    reorderedTasks.splice(nextIndex, 0, movedTask);

    try {
      setProductionAction(`move:${taskId}`);
      const updates = reorderedTasks.map((task, index) => ({
        id: task.id,
        sort_order: index,
      }));

      if (isDemoMode) {
        onDemoSnapshotChange((currentSnapshot) => ({
          ...currentSnapshot,
          jobTasks: currentSnapshot.jobTasks.map((task) => {
            const update = updates.find((item) => item.id === task.id);

            return update ? { ...task, sort_order: update.sort_order } : task;
          }),
        }));
      } else {
        await reorderJobTasks(client, updates);
        await onScrollPreservingReload();
      }
      onNotice("Checklist order updated.");
    } catch (currentError) {
      onError(getCaughtErrorMessage(currentError, "Unable to reorder checklist tasks."));
    } finally {
      setProductionAction(null);
    }
  };

